def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [v for v in counts if v not in (0, background)]
    if not colors:
        return [row[:] for row in grid]
    color = min(colors, key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]

    # Check copies of the colored pattern in all rotations/reflections.
    variants = set()
    for reflect in (False, True):
        for turns in range(4):
            pts = []
            for r, c in points:
                if reflect:
                    c = -c
                for _ in range(turns):
                    r, c = c, -r
                pts.append((r, c))
            min_r = min(r for r, c in pts)
            min_c = min(c for r, c in pts)
            variants.add(tuple(sorted((r - min_r, c - min_c) for r, c in pts)))

    out = [row[:] for row in grid]
    for shape in variants:
        sh = max(r for r, c in shape) + 1
        sw = max(c for r, c in shape) + 1
        for top in range(h - sh + 1):
            for left in range(w - sw + 1):
                cells = [(top + r, left + c) for r, c in shape]
                if all(grid[r][c] == 0 for r, c in cells):
                    for r, c in cells:
                        out[r][c] = color
    return out
